const input = $input.first()?.json || {};

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object || {}, key);
}

function stripOuterQuotes(value) {
  let text = String(value ?? '').trim();
  const pairs = [['"', '"'], ["'", "'"], ['“', '”'], ['‘', '’']];
  for (const [left, right] of pairs) {
    if (text.startsWith(left) && text.endsWith(right) && text.length >= left.length + right.length) {
      text = text.slice(left.length, text.length - right.length).trim();
      break;
    }
  }
  return text;
}

function normalizePath(value) {
  let text = stripOuterQuotes(value).replace(/\\+/g, '/');
  if (text.startsWith('//')) text = '//' + text.slice(2).replace(/\/+/g, '/');
  else text = text.replace(/\/+/g, '/');
  if (text.length > 1 && text.endsWith('/') && !/^[A-Za-z]:\/$/.test(text)) text = text.replace(/\/+$/, '');
  return text;
}

function canonicalAbsolutePath(value) {
  const text = normalizePath(value);
  if (!text) return { absolute: false, value: '', caseInsensitive: false, escapedRoot: false };

  let prefix = '';
  let caseInsensitive = false;
  let parts = [];

  if (/^[A-Za-z]:\//.test(text)) {
    prefix = text.slice(0, 2).toUpperCase() + '/';
    caseInsensitive = true;
    parts = text.slice(3).split('/');
  } else if (text.startsWith('//')) {
    const unc = text.slice(2).split('/').filter(Boolean);
    if (unc.length < 2) return { absolute: false, value: text, caseInsensitive: true, escapedRoot: false };
    prefix = '//' + unc.shift() + '/' + unc.shift();
    caseInsensitive = true;
    parts = unc;
  } else if (text.startsWith('/')) {
    prefix = '/';
    parts = text.slice(1).split('/');
  } else {
    return { absolute: false, value: text, caseInsensitive: false, escapedRoot: false };
  }

  const stack = [];
  let escapedRoot = false;
  for (const part of parts) {
    if (!part || part === '.') continue;
    if (part === '..') {
      if (stack.length) stack.pop();
      else escapedRoot = true;
      continue;
    }
    stack.push(part);
  }

  const separator = prefix.endsWith('/') || stack.length === 0 ? '' : '/';
  return {
    absolute: true,
    value: prefix + separator + stack.join('/'),
    caseInsensitive,
    escapedRoot,
  };
}

function isInsideAllowedRoot(targetPath, rootPath) {
  const target = canonicalAbsolutePath(targetPath);
  const root = canonicalAbsolutePath(rootPath);
  if (!target.absolute || !root.absolute || target.escapedRoot || root.escapedRoot) return false;
  if (target.caseInsensitive !== root.caseInsensitive) return false;
  const targetValue = target.caseInsensitive ? target.value.toLowerCase() : target.value;
  const rootValue = root.caseInsensitive ? root.value.toLowerCase() : root.value;
  const prefix = rootValue.endsWith('/') ? rootValue : rootValue + '/';
  return targetValue === rootValue || targetValue.startsWith(prefix);
}

function toInteger(value, fallback, minimum, maximum) {
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(minimum, Math.min(maximum, parsed));
}

function toStringArray(value) {
  if (Array.isArray(value)) return value.map(normalizePath).filter(Boolean);
  if (typeof value === 'string') {
    const text = value.trim();
    if (!text) return [];
    try {
      const parsed = JSON.parse(text);
      if (Array.isArray(parsed)) return parsed.map(normalizePath).filter(Boolean);
    } catch {}
    return text.split(/[;,\n]/).map(normalizePath).filter(Boolean);
  }
  return [];
}

function normalizeBrowserWindowMode(value) {
  return 'foreground';
}

function normalizeBrowserChannel(value) {
  const channel = String(value ?? '').trim().toLowerCase();
  return channel === 'chromium' ? 'chromium' : 'chrome';
}

function normalizeBrowserRunMode(value) {
  return String(value ?? '').trim().toLowerCase() === 'headless' ? 'headless' : 'headed';
}

function normalizeBrowserControlMode(value) {
  return String(value ?? '').trim() === 'edgeProfileMirror' ? 'edgeProfileMirror' : 'persistentContext';
}

function normalizeScrollBehavior(value) {
  return String(value ?? '').trim().toLowerCase() === 'fixed' ? 'fixed' : 'natural';
}

function sanitizeProfileDirectory(value) {
  const text = String(value ?? '').trim();
  if (!text) return '';
  if (!/^[A-Za-z0-9_. -]{1,120}$/.test(text)) return '';
  if (text.includes('/') || text.includes('\\') || text === '.' || text === '..') return '';
  return text;
}

function toBoolean(value, fallback) {
  if (value === undefined || value === null || value === '') return Boolean(fallback);
  if (value === true || value === false) return value;
  const text = String(value).trim().toLowerCase();
  if (['true', '1', 'yes', 'y'].includes(text)) return true;
  if (['false', '0', 'no', 'n'].includes(text)) return false;
  return Boolean(fallback);
}

function joinPortable(root, relativePath) {
  const base = normalizePath(root).replace(/\/+$/, '');
  const suffix = String(relativePath || '').replace(/^\/+/, '');
  return base + '/' + suffix;
}

function cleanName(value, fallback = 'product') {
  const cleaned = String(value || '')
    .trim()
    .normalize('NFC')
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, '_')
    .replace(/\s+/g, ' ')
    .replace(/[. ]+$/g, '')
    .slice(0, 80);
  return cleaned || fallback;
}

function parseProductUrl(value) {
  const productUrl = String(value ?? '').trim();
  const invalid = () => ({ productUrl, validUrl: false, allowedHost: false, allowedProtocol: false, offerId: '' });
  if (!productUrl || productUrl.length > 8192 || /[\u0000-\u0020\u007f]/.test(productUrl)) return invalid();

  // n8n 2.25.x does not expose the WHATWG URL global inside every Code-node
  // sandbox. Parse only the URL parts needed for validation so the workflow
  // remains portable without require('url') or any extra sandbox permission.
  const match = productUrl.match(/^(https?):\/\/([^\/?#]+)(\/[^?#]*)?(?:\?([^#]*))?(?:#.*)?$/i);
  if (!match) return invalid();
  const protocol = String(match[1] || '').toLowerCase();
  const authority = String(match[2] || '');
  if (!authority || authority.includes('@')) return invalid();
  const hostMatch = authority.match(/^([a-z0-9.-]+)$/i);
  if (!hostMatch) return invalid();

  const host = String(hostMatch[1] || '').toLowerCase();
  const labels = host.split('.');
  const validHost = host.length <= 253 && labels.every(
    (label) => label.length <= 63 && /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label),
  );
  if (!validHost) return invalid();
  const allowedHost = host === '1688.com' || host.endsWith('.1688.com');
  const allowedProtocol = protocol === 'https' || protocol === 'http';
  const pathname = match[3] || '/';
  const pathMatch = pathname.match(/\/offer\/(\d{5,30})(?:\.html)?(?:\/|$)/i);
  let offerId = pathMatch && pathMatch[1] ? pathMatch[1] : '';

  if (!offerId && match[4]) {
    const queryValues = { offerId: null, offer_id: null, id: null };
    for (const pair of String(match[4]).split('&')) {
      const separator = pair.indexOf('=');
      const rawKey = separator >= 0 ? pair.slice(0, separator) : pair;
      const rawValue = separator >= 0 ? pair.slice(separator + 1) : '';
      let key = rawKey;
      let queryValue = rawValue;
      try {
        key = decodeURIComponent(rawKey.replace(/\+/g, ' '));
        queryValue = decodeURIComponent(rawValue.replace(/\+/g, ' '));
      } catch {}
      if (Object.prototype.hasOwnProperty.call(queryValues, key) && queryValues[key] === null) {
        queryValues[key] = queryValue;
      }
    }
    for (const key of ['offerId', 'offer_id', 'id']) {
      if (queryValues[key]) {
        offerId = queryValues[key];
        break;
      }
    }
  }

  if (!/^\d{5,30}$/.test(offerId)) offerId = '';
  return { productUrl, validUrl: true, allowedHost, allowedProtocol, offerId };
}

const isWebhook = Boolean(input.body && typeof input.body === 'object' && (input.headers || input.webhookUrl || input.executionMode));
const body = isWebhook ? input.body : {};
const overrideFields = ['SKU', 'productName', 'parentOutputDir', 'productUrl', 'downloadJobId'];

function coreValue(name) {
  return isWebhook ? body[name] : input[name];
}

const SKU = String(coreValue('SKU') ?? '').trim();
const productName = String(coreValue('productName') ?? '').trim();
const downloadJobId = isWebhook ? String(coreValue('downloadJobId') ?? '').trim().toLowerCase() : '';
const parentInfo = canonicalAbsolutePath(coreValue('parentOutputDir'));
const parentOutputDir = parentInfo.value || normalizePath(coreValue('parentOutputDir'));
const parsedProduct = parseProductUrl(coreValue('productUrl'));
const allowedOutputRoots = toStringArray(input.allowedOutputRoots);
const projectInfo = canonicalAbsolutePath(input.projectRootDir);
const browserProfileInfo = canonicalAbsolutePath(input.browserUserDataDir);
const sourceBrowserProfileInfo = canonicalAbsolutePath(input.sourceBrowserUserDataDir);
const browserExecutableInfo = canonicalAbsolutePath(input.browserExecutablePath);
const browserControlMode = normalizeBrowserControlMode(input.browserControlMode);
const sourceBrowserProfileDirectory = sanitizeProfileDirectory(input.sourceBrowserProfileDirectory);
const browserProfileDirectory = sanitizeProfileDirectory(input.browserProfileDirectory);
const browserChannel = normalizeBrowserChannel(input.browserChannel);
const headless = isWebhook;
const browserRunMode = headless ? 'headless' : 'headed';
const minimizeBrowserWindow = false;
const requireBrowserProfileUnlocked = toBoolean(input.requireBrowserProfileUnlocked, true);
const syncDefaultProfileBeforeRun = false;
const closeEdgeBeforeSync = false;
const preserveTargetLogin = false;
const targetAuthCookieNames = toStringArray(input.targetAuthCookieNames);
const ffmpegInfo = input.ffmpegPath ? canonicalAbsolutePath(input.ffmpegPath) : null;

let downloadConcurrency = toInteger(input.downloadConcurrency, 4, 4, 16);
downloadConcurrency = Math.min(16, Math.max(4, Math.ceil(downloadConcurrency / 4) * 4));

const validationErrors = [];
if (isWebhook) {
  for (const field of overrideFields) {
    if (!hasOwn(body, field) || body[field] === null || String(body[field]).trim() === '') {
      validationErrors.push('Webhook body must include ' + field + '.');
    }
  }
}
if (!/^\d{7}$/.test(SKU)) validationErrors.push('SKU must be exactly 7 digits.');
if (isWebhook && !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(downloadJobId)) {
  validationErrors.push('Webhook body downloadJobId must be a UUID.');
}
const n8nExecutionId = String($execution.id || '').trim();
const safeProductName = cleanName(productName);
const expectedOutputDir = joinPortable(parentOutputDir, SKU + '-' + safeProductName + '-' + n8nExecutionId);
const expectedMetadataPath = joinPortable(expectedOutputDir, 'metadata/1688-media-metadata.json');
const expectedResultFilePath = joinPortable(expectedOutputDir, 'metadata/1688-media-result.json');
if (!/^\d+$/.test(n8nExecutionId)) validationErrors.push('n8nExecutionId must contain digits only.');
if (!productName) validationErrors.push('productName must not be empty.');
if (!parsedProduct.validUrl || !parsedProduct.allowedProtocol || !parsedProduct.allowedHost) {
  validationErrors.push('productUrl must be an HTTP(S) URL on 1688.com or one of its subdomains.');
}
if (parsedProduct.validUrl && parsedProduct.allowedHost && !parsedProduct.offerId) {
  validationErrors.push('productUrl must contain a numeric 1688 offerId.');
}
if (!parentInfo.absolute || parentInfo.escapedRoot) validationErrors.push('parentOutputDir must be an absolute path.');
if (!allowedOutputRoots.length || !allowedOutputRoots.some((root) => isInsideAllowedRoot(parentOutputDir, root))) {
  validationErrors.push('parentOutputDir must be inside an allowedOutputRoots entry.');
}
if (!projectInfo.absolute || projectInfo.escapedRoot) validationErrors.push('projectRootDir must be an absolute path.');
if (!browserProfileInfo.absolute || browserProfileInfo.escapedRoot) validationErrors.push('browserUserDataDir must be an absolute path.');
if (browserControlMode === 'edgeProfileMirror' && (!sourceBrowserProfileInfo.absolute || sourceBrowserProfileInfo.escapedRoot)) {
  validationErrors.push('sourceBrowserUserDataDir must be an absolute path.');
}
if (!browserExecutableInfo.absolute || browserExecutableInfo.escapedRoot) {
  validationErrors.push('browserExecutablePath must be an absolute path.');
}
if (ffmpegInfo && (!ffmpegInfo.absolute || ffmpegInfo.escapedRoot)) {
  validationErrors.push('ffmpegPath must be empty or an absolute path.');
}

const normalized = {
  isWebhook,
  requestSource: isWebhook ? 'webhook' : 'manual',
  validationValid: validationErrors.length === 0,
  validationErrors,
  SKU,
  productName,
  downloadJobId,
  workflowCode: 'E007',
  n8nExecutionId,
  safeProductName,
  expectedOutputDir,
  expectedMetadataPath,
  expectedResultFilePath,
  parentOutputDir,
  productUrl: parsedProduct.productUrl,
  offerId: parsedProduct.offerId,
  allowedOutputRoots,
  projectRootDir: projectInfo.value || normalizePath(input.projectRootDir),
  crawlerScriptPath: joinPortable(projectInfo.value || normalizePath(input.projectRootDir), 'scripts/1688-product-media-downloader.cjs'),
  detailStitcherScriptPath: joinPortable(projectInfo.value || normalizePath(input.projectRootDir), 'scripts/1688-detail-image-stitcher.cjs'),
  idempotencyHelperScriptPath: joinPortable(projectInfo.value || normalizePath(input.projectRootDir), 'scripts/download-idempotency-v1.cjs'),
  browserUserDataDir: browserProfileInfo.value || normalizePath(input.browserUserDataDir),
  browserExecutablePath: browserExecutableInfo.value || normalizePath(input.browserExecutablePath),
  browserProfileDirectory,
  browserControlMode,
  sourceBrowserUserDataDir: sourceBrowserProfileInfo.value || normalizePath(input.sourceBrowserUserDataDir),
  sourceBrowserProfileDirectory,
  syncDefaultProfileBeforeRun,
  closeEdgeBeforeSync,
  preserveTargetLogin,
  targetAuthCookieHostPattern: String(input.targetAuthCookieHostPattern ?? '%'),
  targetAuthCookieNames,
  browserChannel,
  browserRunMode,
  minimizeBrowserWindow,
  requireBrowserProfileUnlocked,
  browserLaunchTimeoutMs: toInteger(input.browserLaunchTimeoutMs, 30000, 10000, 180000),
  browserWindowMode: normalizeBrowserWindowMode(input.browserWindowMode),
  headless,
  humanVerificationMode: isWebhook ? 'failFast' : 'interactive',
  ffmpegPath: ffmpegInfo ? ffmpegInfo.value : '',
  maxMainImages: toInteger(input.maxMainImages, 10, 1, 100),
  maxDetailImages: toInteger(input.maxDetailImages, 80, 0, 300),
  maxVideos: toInteger(input.maxVideos, 3, 0, 10),
  downloadConcurrency,
  pageTimeoutMs: toInteger(input.pageTimeoutMs, 60000, 10000, 180000),
  requestTimeoutMs: toInteger(input.requestTimeoutMs, 30000, 5000, 120000),
  humanVerificationTimeoutMs: toInteger(input.humanVerificationTimeoutMs, 300000, 30000, 900000),
  scrollMaxTimes: toInteger(input.scrollMaxTimes, 20, 1, 80),
  scrollWaitMs: toInteger(input.scrollWaitMs, 1200, 100, 10000),
  scrollBehavior: normalizeScrollBehavior(input.scrollBehavior),
  interactionSeed: String(input.interactionSeed ?? '').trim(),
  maxResponseBodyBytes: toInteger(input.maxResponseBodyBytes, 5242880, 262144, 20971520),
  maxMediaBytes: toInteger(input.maxMediaBytes, 268435456, 1048576, 1073741824),
  nodeExecutable: 'node',
};

const downloaderPayload = {
  SKU: normalized.SKU,
  productName: normalized.productName,
  n8nExecutionId: normalized.n8nExecutionId,
  parentOutputDir: normalized.parentOutputDir,
  allowedOutputRoots: normalized.allowedOutputRoots,
  productUrl: normalized.productUrl,
  browserUserDataDir: normalized.browserUserDataDir,
  browserExecutablePath: normalized.browserExecutablePath,
  browserProfileDirectory: normalized.browserProfileDirectory,
  browserControlMode: normalized.browserControlMode,
  sourceBrowserUserDataDir: normalized.sourceBrowserUserDataDir,
  sourceBrowserProfileDirectory: normalized.sourceBrowserProfileDirectory,
  syncDefaultProfileBeforeRun: normalized.syncDefaultProfileBeforeRun,
  closeEdgeBeforeSync: normalized.closeEdgeBeforeSync,
  preserveTargetLogin: normalized.preserveTargetLogin,
  targetAuthCookieHostPattern: normalized.targetAuthCookieHostPattern,
  targetAuthCookieNames: normalized.targetAuthCookieNames,
  browserChannel: normalized.browserChannel,
  browserRunMode: normalized.browserRunMode,
  minimizeBrowserWindow: normalized.minimizeBrowserWindow,
  requireBrowserProfileUnlocked: normalized.requireBrowserProfileUnlocked,
  browserLaunchTimeoutMs: normalized.browserLaunchTimeoutMs,
  browserWindowMode: normalized.browserWindowMode,
  headless: normalized.headless,
  humanVerificationMode: normalized.humanVerificationMode,
  resultFilePath: normalized.expectedResultFilePath,
  ffmpegPath: normalized.ffmpegPath,
  maxMainImages: normalized.maxMainImages,
  maxDetailImages: normalized.maxDetailImages,
  maxVideos: normalized.maxVideos,
  downloadConcurrency: normalized.downloadConcurrency,
  pageTimeoutMs: normalized.pageTimeoutMs,
  requestTimeoutMs: normalized.requestTimeoutMs,
  humanVerificationTimeoutMs: normalized.humanVerificationTimeoutMs,
  scrollMaxTimes: normalized.scrollMaxTimes,
  scrollWaitMs: normalized.scrollWaitMs,
  scrollBehavior: normalized.scrollBehavior,
  interactionSeed: normalized.interactionSeed,
  maxResponseBodyBytes: normalized.maxResponseBodyBytes,
  maxMediaBytes: normalized.maxMediaBytes,
};

normalized.paramBase64 = Buffer.from(JSON.stringify(downloaderPayload), 'utf8').toString('base64');
normalized.idempotencyPreflightParamBase64 = Buffer.from(JSON.stringify({
  workflowCode: normalized.workflowCode,
  isWebhook: normalized.isWebhook,
  downloadJobId: normalized.downloadJobId,
  requestN8nExecutionId: normalized.n8nExecutionId,
  parentOutputDir: normalized.parentOutputDir,
  allowedOutputRoots: normalized.allowedOutputRoots,
  expectedOutputDir: normalized.expectedOutputDir,
  SKU: normalized.SKU,
  productName: normalized.productName,
  productUrl: normalized.productUrl,
  platformProductId: normalized.offerId,
}), 'utf8').toString('base64');
return [{ json: normalized }];

const current = $input.first()?.json || {};
const normalized = $('Normalize Parameters').first()?.json || {};

function parseLastJsonLine(value) {
  const lines = String(value || '').split(/\r?\n/).map((line) => line.trim()).filter(Boolean).reverse();
  for (const line of lines) {
    try {
      const parsed = JSON.parse(line);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
    } catch {}
  }
  return null;
}

const parsed = parseLastJsonLine(current.stdout);
let outcome = parsed && typeof parsed.action === 'string' ? parsed : null;
if (!outcome) {
  const helperResult = parsed && typeof parsed === 'object' ? parsed : {};
  outcome = {
    action: 'error',
    idempotency: null,
    response: {
      success: false,
      status: String(helperResult.status || 'idempotency_preflight_error'),
      httpStatus: Number(helperResult.httpStatus || 500),
      platform: '1688',
      SKU: normalized.SKU || '',
      productName: normalized.productName || '',
      productUrl: normalized.productUrl || '',
      outputDir: '',
      errors: Array.isArray(helperResult.errors)
        ? helperResult.errors
        : ['Idempotency preflight did not return a valid outcome.'],
      warnings: String(current.stderr || '').trim() ? [String(current.stderr).trim().slice(0, 1000)] : [],
      downloadJobId: normalized.downloadJobId || '',
      idempotencyState: 'failed',
      idempotencyReplay: false,
      ownerN8nExecutionId: '',
      requestN8nExecutionId: normalized.n8nExecutionId || '',
    },
  };
}

let downloaderPayload = {};
try {
  downloaderPayload = JSON.parse(Buffer.from(String(normalized.paramBase64 || ''), 'base64').toString('utf8'));
} catch {}
downloaderPayload.idempotency = outcome.idempotency || { enabled: false };
const ownerN8nExecutionId = String(outcome.ownerN8nExecutionId || normalized.n8nExecutionId || '');
const ownerOutputDir = String(outcome.outputDir || normalized.expectedOutputDir || '');
downloaderPayload.n8nExecutionId = ownerN8nExecutionId;
downloaderPayload.resultFilePath = ownerOutputDir
  ? ownerOutputDir.replace(/\/+$/, '') + '/metadata/1688-media-result.json'
  : normalized.expectedResultFilePath;

return [{ json: {
  ...normalized,
  requestN8nExecutionId: normalized.n8nExecutionId || '',
  idempotencyAction: String(outcome.action || 'error'),
  idempotency: outcome.idempotency || null,
  idempotencyResponse: outcome.response || null,
  recoveredDownloadResult: outcome.downloadResult || null,
  ownerN8nExecutionId,
  ownerOutputDir,
  expectedOutputDir: ownerOutputDir,
  expectedMetadataPath: ownerOutputDir ? ownerOutputDir.replace(/\/+$/, '') + '/metadata/1688-media-metadata.json' : '',
  expectedResultFilePath: ownerOutputDir ? ownerOutputDir.replace(/\/+$/, '') + '/metadata/1688-media-result.json' : '',
  paramBase64: Buffer.from(JSON.stringify(downloaderPayload), 'utf8').toString('base64'),
} }];

const input = $input.first()?.json || {};
const response = input.idempotencyResponse && typeof input.idempotencyResponse === 'object'
  ? input.idempotencyResponse
  : {
    success: false,
    status: 'idempotency_preflight_error',
    httpStatus: 500,
    errors: ['Idempotency routing reached a terminal branch without a response.'],
    warnings: [],
  };
return [{ json: response }];

const input = $input.first()?.json || {};
const recovered = input.recoveredDownloadResult && typeof input.recoveredDownloadResult === 'object'
  ? input.recoveredDownloadResult
  : {
    success: false,
    status: 'idempotency_recovery_invalid',
    httpStatus: 500,
    errors: ['Idempotency recovery did not provide a media result.'],
    warnings: [],
  };
return [{ json: { ...recovered, resultSource: 'idempotency_artifact_recovery' } }];

const current = $input.first()?.json || {};
const normalized = $('Parse Idempotency Preflight').first()?.json || {};

function parseLastJsonLine(value) {
  const lines = String(value || '').split(/\r?\n/).map((line) => line.trim()).filter(Boolean).reverse();
  for (const line of lines) {
    try {
      const parsed = JSON.parse(line);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
    } catch {}
  }
  return null;
}

function textArray(value) {
  return Array.isArray(value) ? value.filter((entry) => entry !== null && entry !== undefined).map(String) : [];
}

function mediaItems(value) {
  if (!Array.isArray(value)) return [];
  return value.map((item, offset) => ({
    index: Number.isFinite(Number(item?.index)) ? Number(item.index) : offset + 1,
    url: String(item?.url || ''),
    localPath: String(item?.localPath || ''),
    fileName: String(item?.fileName || ''),
    contentType: String(item?.contentType || ''),
    sizeBytes: Number.isFinite(Number(item?.sizeBytes)) ? Number(item.sizeBytes) : 0,
    source: String(item?.source || ''),
  }));
}

function normalizeIdentityPath(value) {
  let text = String(value || '').trim().replace(/\\+/g, '/').replace(/^([A-Za-z]:)\/+/, '$1/');
  while (text.length > 1 && text.endsWith('/') && !/^[A-Za-z]:\/$/.test(text)) text = text.slice(0, -1);
  return /^[A-Za-z]:\//.test(text) ? text.toLowerCase() : text;
}

function verifyFallbackIdentity(result, sourceName) {
  const mismatches = [];
  if (String(result?.SKU || '') !== String(normalized.SKU || '')) mismatches.push('SKU');
  if (String(result?.offerId || '') !== String(normalized.offerId || '')) mismatches.push('offerId');
  if (normalizeIdentityPath(result?.outputDir) !== normalizeIdentityPath(normalized.expectedOutputDir)) mismatches.push('outputDir');
  if (mismatches.length) throw new Error(sourceName + ' identity mismatch: ' + mismatches.join(', ') + '.');
  return result;
}

function readResultFileFallback() {
  const resultPath = String(normalized.expectedResultFilePath || '').trim();
  if (!resultPath) throw new Error('Expected result file path is unavailable.');
  const fs = require('fs');
  if (!fs.existsSync(resultPath)) throw new Error('Expected result file does not exist: ' + resultPath);
  return verifyFallbackIdentity(JSON.parse(fs.readFileSync(resultPath, 'utf8')), 'Result file');
}

function readMetadataFallback() {
  const metadataPath = String(normalized.expectedMetadataPath || '').trim();
  if (!metadataPath) throw new Error('Expected metadata path is unavailable.');
  const fs = require('fs');
  if (!fs.existsSync(metadataPath)) throw new Error('Expected metadata file does not exist: ' + metadataPath);
  const metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf8'));
  if (!metadata || typeof metadata.result !== 'object') throw new Error('Metadata does not contain a result object.');
  return verifyFallbackIdentity(metadata.result, 'Metadata');
}

function fallbackResult(message) {
  return {
    success: false,
    status: 'internal_error',
    httpStatus: 500,
    platform: '1688',
    SKU: normalized.SKU || '',
    productName: normalized.productName || '',
    productUrl: normalized.productUrl || '',
    offerId: normalized.offerId || '',
    outputDir: '',
    revision: 0,
    mainImageCount: 0,
    detailImageCount: 0,
    videoCount: 0,
    mainImages: [],
    detailImages: [],
    videos: [],
    metadataPath: '',
    needHumanVerification: false,
    humanVerificationResolved: false,
    humanVerificationStatus: 'not_required',
    humanVerificationScreenshotPath: '',
    browserProfileBusy: false,
    browserProfileLocked: false,
    profileStatus: 'unknown',
    browserChannel: normalized.browserChannel || 'chrome',
